#include <string.h>
int validparentheses(char *s){
    char stack[strlen(s)];
    int i = 0;
    while (*s){
        if (*s == '{' || *s == '[' || *s == '(')
            stack[i++] = *s;
        else if (*s == '}' || *s == ']' || *s == ')'){
            if (!i)
                return 0;
            if ((*s == '}' && stack[i - 1] != '{') 
                || (*s == ']' && stack[i - 1] != '[')
                || (*s == ')' && stack[i - 1] != '('))
                return 0;
            i--;
        }
        s++;
    }
    return (i == 0);
}
